script:
if not doc.customer:
    customer = frappe.get_doc({
        "doctype": "Customer",
        "customer_name": doc.student_name,
        "customer_type": "Individual",
        "customer_group": "Individual" if frappe.db.exists("Customer Group", "Individual") else frappe.db.get_single_value("Selling Settings", "customer_group"),
        "territory": frappe.db.get_single_value("Selling Settings", "territory"),
    })
    customer.insert(ignore_permissions=True)
    frappe.db.set_value("Student", doc.name, "customer", customer.name)
